// Production main/preload/renderer with controlled native transports and real local tools.
const fs=require('node:fs'),path=require('node:path'),Module=require('node:module'),assert=require('node:assert/strict');
const {execFileSync}=require('node:child_process'),{randomUUID}=require('node:crypto'),{setTimeout:delay}=require('node:timers/promises'),{app,ipcMain}=require('electron');
app.disableHardwareAcceleration();const root=process.env.AI_DECK_QA_ROOT,appDir=process.env.AI_DECK_QA_APP,profile=process.env.AI_DECK_PROFILE_DIRECTORY=path.join(root,'profile');
process.env.CODEX_HOME=path.join(root,'codex');process.env.CLAUDE_CONFIG_DIR=path.join(root,'claude');for(const dir of [profile,process.env.CODEX_HOME,process.env.CLAUDE_CONFIG_DIR])fs.mkdirSync(dir,{recursive:true});
const {newTask}=require(path.join(appDir,'tasks.cjs')),{contextSnapshot}=require(path.join(appDir,'context-notes.cjs'));
const git=(repo,args)=>execFileSync('git',['-c','core.hooksPath=NUL','-c','core.autocrlf=false','-c','user.name=QA','-c','user.email=qa@example.invalid',...args],{cwd:repo,windowsHide:true,encoding:'utf8'}).trim();
