for(const entry of cases){const {repo,marker}=entry;fs.mkdirSync(repo,{recursive:true});git(repo,['init','-q','-b','main']);fs.writeFileSync(path.join(repo,'source.js'),`module.exports='${marker}';\n`);git(repo,['add','.']);git(repo,['commit','-qm','fixture']);
 const origin=path.join(repo,'knowledge.md'),text='SHARED_'+marker;fs.writeFileSync(origin,text);const note={id:'shared-'+entry.index,name:'Knowledge',source:'Project',text,enabled:true,provenance:contextSnapshot(repo,text,{kind:'file',file:origin})};fs.writeFileSync(origin,'UNSELECTED_NEW_'+marker);
 const skill={id:'skill-'+entry.index,name:'Scoped skill',source:'Skill',text:'SKILL_'+marker,provenance:contextSnapshot(repo,'SKILL_'+marker)};
 const task=newTask();task.title='Sharing '+marker;entry.id=task.id;entry.skill=skill.id;entry.note=note.id;
 const scope={repo:fs.realpathSync.native(repo),branch:'main',base:git(repo,['rev-parse','HEAD'])};task.teamDecisions=[{id:'own',text:'DECISION_'+marker,scope},{id:'foreign',text:'FOREIGN_DECISION',scope:{...scope,repo:path.join(root,'unrelated')}},{id:'legacy',text:'LEGACY_DECISION',scope:{branch:'main',base:scope.base}}];
 workspaces[repo]={repo,tasks:[task],currentTask:task.id,notes:[note,skill,{id:'disabled-'+entry.index,name:'Disabled',source:'Project',text:'DISABLED_'+marker,enabled:false}],plugins:[],instructions:'',shareNewFiles:true};
}
const foreign={id:'foreign-note',name:'FOREIGN_PRIVATE_TITLE',source:'Project',text:'FOREIGN_PRIVATE_BODY',enabled:true,provenance:contextSnapshot(cases[1].repo,'FOREIGN_PRIVATE_BODY')};workspaces[cases[0].repo].notes.push(foreign);
const executables={};for(const provider of ['codex','claude']){executables[provider]=path.join(root,provider+'.exe');fs.writeFileSync(executables[provider],'fixture')}
fs.writeFileSync(path.join(profile,'workspace-state.json'),JSON.stringify({executables,currentRepo:cases[0].repo,closeToTray:false,lowMemory:false,preferences:{notifications:'off'},workspaces}));
const report={calls:[],cases:[]},save=()=>fs.writeFileSync(path.join(root,'result.json'),JSON.stringify(report,null,2));let current;
const engines=require(path.join(appDir,'engines.cjs')),capture=engines.capture;
engines.capture=(exe,args,options)=>/^git(?:\.exe)?$/i.test(path.basename(exe))?capture(exe,args,options):Promise.resolve({code:0,stderr:'',stdout:args[0]==='--version'?/claude/.test(exe)?'2.1.319 (Claude Code)':'codex-cli 0.0.0':args[0]==='auth'?JSON.stringify({loggedIn:true}):'Logged in using ChatGPT'});engines.inspectClaude=async()=>({models:[]});
async function turn(provider,id,cwd,prompt,readOnly,plugins,emit){const project=plugins.find(plugin=>plugin.name==='ai_deck_project');report.calls.push({case:current.index,provider,id,readOnly,projectTools:Boolean(project)});emit({type:'provider-call'});
 assert.ok(!prompt.includes('SHARED_'+current.other));assert.ok(!prompt.includes('UNSELECTED_NEW_'));assert.ok(!prompt.includes('DISABLED_'));assert.ok(!prompt.includes('FOREIGN_PRIVATE'));assert.ok(!prompt.includes('FOREIGN_DECISION'));assert.ok(!prompt.includes('LEGACY_DECISION'));
 if(!readOnly){assert.ok(prompt.includes('SHARED_'+current.marker));assert.ok(prompt.includes('SKILL_'+current.marker));assert.ok(prompt.includes('source changed since capture'));assert.ok(prompt.includes('DECISION_'+current.marker));assert.ok(project,'Writer retains project tools');
  const response=await fetch(project.url,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({jsonrpc:'2.0',id:1,method:'tools/call',params:{name:'file_read',arguments:{file:'source.js'}}})});const text=JSON.stringify(await response.json());assert.ok(text.includes(current.marker));assert.ok(!text.includes(current.other));fs.appendFileSync(path.join(cwd,'source.js'),'// scoped edit\n');
 }else{assert.equal(project,undefined,'Report-only reviewer does not receive the built-in repository tools');assert.ok(!prompt.includes('SHARED_'+current.marker));assert.ok(!prompt.includes('SKILL_'+current.marker));}
 const text=readOnly?'AI_DECK_REVIEW: BLOCKED\nR1 BLOCKED — The selected report does not substantiate current code; the user excluded the diff.':'Updated the scoped source. Verification needs a current review.';
 emit({type:'message',key:randomUUID(),text});return{status:'completed',answer:text,sessionId:id};}
engines.CodexEngine=class{constructor(_exe,cwd,plugins,emit){this.cwd=cwd;this.plugins=plugins;this.emit=emit}async initialize(){}async shutdown(){}close(){}async interrupt(){}async request(method,payload){if(method==='config/read')return{config:{}};if(method==='model/list')return{data:[{model:'gpt-fixture',displayName:'GPT'}]};if(method==='thread/start'||method==='thread/resume')return{thread:{id:payload.threadId??randomUUID()},model:'gpt-fixture'};if(method==='thread/name/set')return{};if(method==='thread/list')return{data:[]};throw Error(method)}async run(id,cwd,prompt,readOnly){return turn('codex',id,cwd,prompt,readOnly,this.plugins,this.emit)}};
engines.runClaude=(_exe,cwd,prompt,plugins,resume,emit,options)=>({done:turn('claude',resume??randomUUID(),cwd,prompt,options.role!=='write',plugins,emit),canSteer(){return false},close(){},async stop(){}});
const handle=ipcMain.handle.bind(ipcMain);ipcMain.handle=(key,fn)=>handle(key,(...args)=>key==='deck:quota-summary'?null:fn(...args));
app.once('browser-window-created',(_,win)=>win.webContents.once('did-finish-load',async()=>{const js=code=>win.webContents.executeJavaScript(code,true),api=(key,payload)=>js(`window.aiDeck[${JSON.stringify(key)}](${JSON.stringify(payload)??''})`),wait=async(fn,label)=>{const end=Date.now()+20000;while(Date.now()<end){if(await fn())return;await delay(30)}throw Error('Timeout '+label)};
 try{await wait(()=>js(`Boolean(document.querySelector('header.thread-top'))&&!document.querySelector('.deck-startup')`),'startup');
  for(current of cases){await api('switch-task',{repo:current.repo,id:current.id});const start=report.calls.length;
   await api('run',{repo:current.repo,taskId:current.id,mode:current.writer==='codex'?'build-review':'claude-build-review',prompt:'Implement the scoped source update. R1: report evidence without guessing.',skillIds:[current.skill],teamOptions:{turnLimit:2,context:{writerNotes:[current.note,current.skill,...(!current.index?['foreign-note']:[])],reviewerNotes:[],diff:false,history:false,decisions:true}}});
   await wait(async()=>{const state=await api('state');return !state.jobs.length&&state.workspace.runHistory.at(-1)?.finishedAt},'provider completion');assert.equal(report.calls.length-start,2,'One builder and one report-only reviewer');const state=await api('state');assert.equal(state.workspace.runHistory.at(-1).collaboration.verdict,'blocked');report.cases.push({writer:current.writer,passed:true});save();
  }report.passed=true;
 }catch(error){report.error=error.stack}finally{save();app.quit()}
}));
const main=path.join(appDir,'main.cjs'),boot=new Module(main,module);boot.filename=main;boot.paths=Module._nodeModulePaths(appDir);boot._compile(fs.readFileSync(main,'utf8').replace('width: 1240, height: 800','show: false, width: 1240, height: 800').replace('preload: path.join(__dirname, "preload.cjs"), contextIsolation','offscreen: true, backgroundThrottling: false, preload: path.join(__dirname, "preload.cjs"), contextIsolation').replace('read: createUpdateReader({ capture,','read: async () => [], unusedReader: createUpdateReader({ capture,'),main);
